/**
 * Typed access to the nuclide table `../data/nuclides.json` (generated by tools/data/build_nuclides.py from an
 * IAEA snapshot). The model knows only this format, never the source's.
 */
import raw from '../data/nuclides.json';

export type DecayCode =
  | 'b-' | 'b+' | 'ec' | 'ec/b+' | 'a' | 'p' | '2p' | 'n' | '2n'
  | 'b-n' | 'b-2n' | 'b-3n' | 'b-4n' | 'b-p' | 'b-a' | 'b+p' | 'b+2p' | 'b+a' | '2b-' | '2b+' | 'sf';
export type NuclideStatus = 'stable' | 'longLived' | 'radioactive' | 'fleeting' | 'incomplete';
export interface Branch { readonly code: DecayCode; readonly share: number }
export interface NuclideRef { readonly z: number; readonly n: number }
export interface Nuclide extends NuclideRef {
  readonly a: number;
  /** Seconds; `null` — unknown. */
  readonly halfLife: number | 'stable' | null;
  /** Shares sum to 1, largest first. */
  readonly branches: readonly Branch[];
  /** Percent in nature. */
  readonly abundance: number | null;
  /** keV. */
  readonly massExcess: number | null;
  /** Year. */
  readonly discovered: number | null;
  readonly status: NuclideStatus;
}

export const AGE_OF_UNIVERSE_S = 4.35e17;
export const FLEETING_BELOW_S = 1;
export const MAX_Z = 118;
export const MAX_N = 178;

type RawRow = [
  z: number, n: number, halfLife: number | 'stable' | null, branches: [DecayCode, number][],
  abundance: number | null, massExcess: number | null, discovered: number | null,
];
interface RawTable {
  neutron: { massExcess: number; halfLife: number };
  symbols: string[];
  nuclides: RawRow[];
}
const table = raw as unknown as RawTable;

function statusOf(halfLife: number | 'stable' | null, branches: readonly Branch[]): NuclideStatus {
  if (halfLife === 'stable') return 'stable';
  if (halfLife !== null && halfLife > AGE_OF_UNIVERSE_S) return 'longLived';
  if (branches.length === 0) return 'incomplete';
  if (halfLife === null || halfLife < FLEETING_BELOW_S) return 'fleeting';
  return 'radioactive';
}

const list: readonly Nuclide[] = table.nuclides.map(([z, n, halfLife, rawBranches, abundance, massExcess, discovered]) => {
  const branches = rawBranches.map(([code, share]): Branch => ({ code, share }));
  return { z, n, a: z + n, halfLife, branches, abundance, massExcess, discovered, status: statusOf(halfLife, branches) };
});

export function nuclideKey(z: number, n: number): string {
  return `${z}-${n}`;
}

const byKey = new Map<string, Nuclide>(list.map((x) => [nuclideKey(x.z, x.n), x]));
const byZ = new Map<number, Nuclide[]>();
for (const x of list) {
  const group = byZ.get(x.z);
  if (group) group.push(x);
  else byZ.set(x.z, [x]);
}
const natural: readonly Nuclide[] = list.filter((x) => x.abundance !== null);

export const NUCLIDE_COUNT = list.length;
export const NEUTRON_MASS_EXCESS: number = table.neutron.massExcess;
export const SOURCE_SYMBOLS: readonly string[] = table.symbols;
/** Mass excess of ¹H (keV). */
export const HYDROGEN_MASS_EXCESS: number = byKey.get(nuclideKey(1, 0))!.massExcess!;

export function getNuclide(z: number, n: number): Nuclide | undefined {
  return byKey.get(nuclideKey(z, n));
}
export function hasNuclide(z: number, n: number): boolean {
  return byKey.has(nuclideKey(z, n));
}
/** All nuclides, by z then n. */
export function allNuclides(): readonly Nuclide[] {
  return list;
}
/** Isotopes of one element, by n. */
export function isotopesOf(z: number): readonly Nuclide[] {
  return byZ.get(z) ?? [];
}
export function naturalNuclides(): readonly Nuclide[] {
  return natural;
}
/** Binding energy per nucleon (keV); null without a mass excess. */
export function bindingPerNucleon(x: Nuclide): number | null {
  if (x.massExcess === null) return null;
  return (x.z * HYDROGEN_MASS_EXCESS + x.n * NEUTRON_MASS_EXCESS - x.massExcess) / x.a;
}
